1	import type { Container } from "@harbor/dispatch/types";
2	
3	export function teuOf(container: Container): number {
4	  switch (container.lengthFt) {
5	    case 20:
6	      return 1;
7	    case 40:
8	      return 2;
9	    case 45:
10	      return 2;
11	    default:
12	      throw new RangeError(`unsupported container length: ${container.lengthFt}`);
13	  }
14	}
15	
16	export function manifestTeu(containers: readonly Container[]): number {
17	  return containers.reduce((sum, c) => sum + teuOf(c), 0);
18	}
19	
20	export function verifiedGrossMassTonnes(container: Container): number {
21	  if (container.cargoKg < 0 || container.tareKg < 0) {
22	    throw new RangeError(`negative mass on ${container.id}`);
23	  }
24	  return Math.round(container.cargoKg) / 1000;
25	}
26	
27	export function manifestWeightTonnes(containers: readonly Container[]): number {
28	  const kg = containers.reduce((sum, c) => sum + Math.round(verifiedGrossMassTonnes(c) * 1000), 0);
29	  return kg / 1000;
30	}
31	
32	export function reeferCount(containers: readonly Container[]): number {
33	  return containers.filter((c) => c.reefer === true).length;
34	}
